function actor(){return state.role==='admin'?'Demo administrator':'Demo editor';}
const byId=id=>state.tests.find(t=>t.id===id);
function pendingKeys(t){return FIELDS.map(f=>f.key).filter(k=>t.pending[k]);}
function deferred(t){return pendingKeys(t).some(k=>t.decisions[k]?.choice==='defer');}
