function retained(t){return FIELDS.some(f=>['olsd','custom'].includes(t.decisions[f.key]?.choice)&&!t.pending[f.key]&&t.epic[f.key]!=null&&!equal(t.proposed[f.key],t.epic[f.key],f.key));}
function approved(t){return !!t.approval&&!t.approval.outdated&&t.approval.signature===outputSig(t)&&!t.blocked&&!pendingKeys(t).length;}
function currentExport(t){return [...state.exports].reverse().find(x=>x.tests.some(v=>v.id===t.id&&outputSig(v)===outputSig(t)));}
function confirmed(t){const x=currentExport(t);return !!x?.check?.rows.find(r=>r.id===t.id&&r.matches&&!r.extras.length)&&!t.approval?.outdated;}
function canApprove(t){return !t.blocked&&!pendingKeys(t).length&&changedKeys(t).length>0&&!approved(t)&&included(t).every(k=>String(t.proposed[k]??'').trim());}
