function workbookFor(x,g){const headers=['Test Number','Test Name','ARUP Test Number','Test Managed By','Use ARUP Test Name','Test Id',...g.fields.filter(k=>k!=='name').map(k=>EXPORT_LABELS[k])];const rows=[headers,...g.ids.map(id=>{const t=x.tests.find(t=>t.id===id);return [t.number,t.proposed.name,t.vendor.arupTestNumber,t.vendor.testManagedBy,t.vendor.useArupTestName,t.id,...g.fields.filter(k=>k!=='name').map(k=>k==='labs'?t.proposed[k].split('\n').map(xml).join('<br />'):t.proposed[k])];})];const sheet=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${rows.map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>`<c r="${columnName(j)}${i+1}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`).join('')}</row>`).join('')}</sheetData></worksheet>`;const files=[{name:'[Content_Types].xml',content:'<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'},{name:'_rels/.rels',content:'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'},{name:'xl/workbook.xml',content:'<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Tests" sheetId="1" r:id="rId1"/></sheets></workbook>'},{name:'xl/_rels/workbook.xml.rels',content:'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>'},{name:'xl/worksheets/sheet1.xml',content:sheet}];return new Blob([zipFiles(files)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});}
function fileName(x,index){if(x.fileNames?.[index])return x.fileNames[index];const g=x.groups[index],test=x.tests.find(t=>t.id===g.ids[0]);return `DEMO_OLSD_${g.ids.length===1?test.number||test.id:g.ids.length+'_tests'}_${index+1}.xlsx`;}
function downloadExcel(x,index){const url=URL.createObjectURL(workbookFor(x,x.groups[index])),a=document.createElement('a');a.href=url;a.download=fileName(x,index);a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function pendingOf(t){return activeKeys(t);}
const BULK_KEYS=['name','labs'];
function reviewGroup(t){const keys=pendingOf(t);if(keys.length>1)return 'multi';return BULK_KEYS.includes(keys[0])?keys[0]:'other';}
function savedWording(t,k){return t.pending[k]?.source==='Catalog'&&!equal(t.proposed[k],t.olsd[k],k);}
function bulkKeys(t){return pendingOf(t).filter(k=>BULK_KEYS.includes(k)&&t.epic[k]!=null&&!savedWording(t,k));}
function selectionKeys(t){const keys=bulkKeys(t);return keys.length?keys:['review'];}
function reviewOrder(rows){const blocked=state.role==='admin'?rows.filter(t=>t.blocked):[],by=g=>rows.filter(t=>!t.blocked&&reviewGroup(t)===g);return [...blocked,...by('multi'),...by('name'),...by('labs'),...by('other')];}
function displayRows(){const rows=baseRows();return ui.tab==='review'&&!ui.query?reviewOrder(rows):rows;}
function changeLine(t,k){const v=display(t),saved=t.decisions[k]?.choice,chosen=v.decisions[k]?.choice,inline=bulkKeys(t).includes(k);return `<div class="change-line" data-row="${t.id}|${k}"><small class="line-label">${e(label(k))}</small><div class="line-value">${savedWording(t,k)?`<span class="saved-wording">Saved wording: ${e(t.proposed[k])}</span><br>Open this test to review the change.`:inline?itemValue(t,k):'Open this test to review the change.'}${chosen!==saved?` <span class="status waiting">Unsaved</span>`:''}</div>${inline?`<div class="inline-choices"><button data-inline="${t.id}|${k}|epic" aria-pressed="${chosen==='epic'}" class="choice-small ${chosen==='epic'?'selected':''}">Use Epic</button><button data-inline="${t.id}|${k}|olsd" aria-label="Keep what is in the OLSD" aria-pressed="${chosen==='olsd'}" class="choice-small ${chosen==='olsd'?'selected':''}">Keep</button></div>`:'<span></span>'}</div>`;}
function testRow(t){const keys=pendingOf(t),pick=selectionKeys(t),on=pick.every(k=>ui.selected.has(t.id+'|'+k));return `<article class="test-row" data-test-row="${t.id}"><div class="test-row-head"><label class="row-select"><span class="sr-only">Select ${e(t.title)}</span><input type="checkbox" data-select-test="${t.id}" ${on?'checked':''}></label><div><button class="entry-title" data-test="${t.id}">${e(t.title)}</button><small>${e(t.number)} · ${e(t.section)} · ${keys.length} ${keys.length===1?'change':'changes'}</small></div><button class="open-entry" data-test="${t.id}" aria-label="Open ${e(t.title)}">›</button></div>${keys.map(k=>changeLine(t,k)).join('')}</article>`;}
function baseRows(){let rows=state.tests.filter(t=>(ui.query?true:matches(t,ui.tab==='all'?ui.allFilter:ui.tab))&&(ui.lab==='all'||t.section===ui.lab));if(ui.query){const q=ui.query.toLowerCase();rows=rows.filter(t=>`${t.title} ${t.number} ${t.id}`.toLowerCase().includes(q));}return rows;}
function stageCounts(){return {review:state.tests.filter(toReview).length,approve:state.tests.filter(canApprove).length,download:state.tests.filter(ready).length,all:state.tests.length};}
function itemValue(t,k){if(k==='labs'){const old=t.olsd[k].split('\n'),next=(t.epic[k]||'').split('\n');const added=next.filter(x=>!old.includes(x)),removed=old.filter(x=>!next.includes(x));return `${added.map(x=>`<ins>+ ${e(x)}</ins>`).join('<br>')}${added.length&&removed.length?'<br>':''}${removed.map(x=>`<del>− ${e(x)}</del>`).join('<br>')}`||e(t.epic[k]);}const d=diffPair(t.olsd[k],t.epic[k]);return `<span class="old-value">${d.before}</span><span class="arrow" aria-hidden="true"> → </span><span>${d.after}</span>`;}
function inlineRow(t,k){if(savedWording(t,k))return testRow(t);const v=display(t),chosen=v.decisions[k]?.choice,unsaved=changesFor(v).length>0;return `<article class="change-row" data-row="${t.id}|${k}"><label class="row-select"><span class="sr-only">Select ${e(t.title)}</span><input type="checkbox" data-select="${t.id}|${k}" ${ui.selected.has(t.id+'|'+k)?'checked':''}></label><div class="change-content"><button class="entry-title" data-test="${t.id}">${k==='name'?itemValue(t,k):e(t.title)}</button>${k==='labs'?`<div class="inline-change"><small>Catalog now: ${e(t.olsd[k])}</small><span>Epic: ${diffPair(t.olsd[k],t.epic[k]).after}</span></div>`:''}<small>${e(t.number)} · ${e(t.section)}${unsaved?' · <span class="status waiting">Unsaved</span>'+ (chosen==='defer'?' · Decide later':''):''}</small></div><div class="inline-choices"><button data-inline="${t.id}|${k}|epic" aria-pressed="${chosen==='epic'}" class="choice-small ${chosen==='epic'?'selected':''}">Use Epic</button><button data-inline="${t.id}|${k}|olsd" title="Keep what is in the OLSD" aria-label="Keep what is in the OLSD" aria-pressed="${chosen==='olsd'}" class="choice-small ${chosen==='olsd'?'selected':''}">Keep</button></div><button class="open-entry" data-test="${t.id}" aria-label="Open ${e(t.title)}">›</button></article>`;}
function reviewList(rows){let html='';if(state.role==='admin'){const blocked=rows.filter(t=>t.blocked);if(blocked.length)html+=`<section class="list-section"><h2>Waiting on a lab name (${blocked.length})</h2>${blocked.map(t=>plainRow(t)).join('')}</section>`;}
 const section=(g,title,row,selectable=true)=>{const all=rows.filter(t=>!t.blocked&&reviewGroup(t)===g),visible=all.slice(0,ui.limit);if(!all.length)return '';const on=all.every(t=>selectionKeys(t).every(k=>ui.selected.has(t.id+'|'+k)));return `<section class="list-section" data-change-group="${g}"><div class="section-heading"><h2>${title} (${all.length})</h2>${selectable?`<button class="link" data-select-section="${g}">${on?'Clear selection':'Select all '+all.length}</button>`:''}</div>${visible.map(row).join('')}${all.length>visible.length?`<button class="link load-more" data-action="load-more">Show ${Math.min(30,all.length-visible.length)} more</button>`:''}</section>`;};
 html+=section('multi','More than one change',testRow)+section('name','Name changes',t=>inlineRow(t,'name'))+section('labs','Lab changes',t=>inlineRow(t,'labs'))+section('other','Other changes',testRow);
 if(!html){const n=state.tests.filter(canApprove).length;html=`<div class="empty"><h2>All caught up.</h2><p>${n?n+' change'+(n===1?' needs':'s need')+' approval.':'No changes need review.'}</p>${n&&!ui.saveResult?.approve?'<button class="primary" data-tab="approve">Go to To approve</button>':''}</div>`;}return html;}
function plainRow(t){const summary=ui.tab==='all'&&['kept','later'].includes(ui.allFilter)?FIELDS.map(f=>f.key).filter(k=>ui.allFilter==='later'?t.decisions[k]?.choice==='defer':['olsd','custom'].includes(t.decisions[k]?.choice)&&t.epic[k]!=null&&!equal(t.proposed[k],t.epic[k],k)).map(k=>`<p class="decision-summary">${e(label(k))}: ${ui.allFilter==='later'?'Set aside · Epic: '+e(t.epic[k]):'Kept: '+e(t.proposed[k])}${t.decisions[k].note?' · '+e(t.decisions[k].note):''}</p>`).join(''):'';return `<article class="catalog-row"><div><button class="entry-title" data-test="${t.id}">${e(t.title)}</button><small>${e(t.number)} · ${e(t.section)}</small>${summary}</div><div>${plainBadge(t)}</div><button class="open-entry" data-test="${t.id}" aria-label="Open ${e(t.title)}">›</button></article>`;}
function valuesChanged(t,keys=changedKeys(t),editable=false){return keys.map(k=>{const d=diffPair(t.olsd[k],t.proposed[k]);return `<div class="saved-change" data-saved-change="${k}"><div class="section-heading"><h3>${e(label(k))}</h3>${editable?`<button class="link" data-edit-field="${k}">Edit</button>`:''}</div><div class="old-new"><div><small>Catalog now</small><div class="value">${d.before||'Empty'}</div></div><div><small>After this update</small><div class="value">${d.after||'Empty'}</div></div></div>${editable&&ui.edits.has(t.id+':'+k)?entryEditor(display(t),k):''}</div>`;}).join('');}
function approveList(rows){if(!rows.length){const readyIds=ui.justApproved.filter(id=>ready(byId(id)));return `<div class="empty"><h2>${readyIds.length?readyIds.length+' approved.':'Nothing waiting for approval.'}</h2><p>${readyIds.length?(fileCount(readyIds)>1?'These tests update different parts of the catalog, so OLSD needs separate files.':'The update is ready to download.'):'Saved changes will appear here.'}</p></div>`;}
 return `<div class="section-heading"><p class="context-note">Approving doesn’t change OLSD. You’ll download a file and import it.</p><div><span>${rows.filter(t=>ui.approvalSelection.has(t.id)).length} selected</span> · <button class="link" data-action="select-all-approvals">${rows.every(t=>ui.approvalSelection.has(t.id))?'Clear selection':'Select all '+rows.length}</button></div></div>${rows.map(t=>`<article class="approval-row" data-approval-row="${t.id}"><div class="section-heading"><button class="entry-title" data-test="${t.id}">${e(t.title)}</button><span>${e(t.number)}</span></div>${valuesChanged(t)}<div class="row-actions"><label class="approval-pick"><input type="checkbox" data-approve-select="${t.id}" aria-label="Select ${e(t.title)} for approval" ${ui.approvalSelection.has(t.id)?'checked':''}> Select</label><button data-approve="${t.id}">Approve</button><button class="link" data-send-back="${t.id}">Send back to review</button></div></article>`).join('')}`;}
function downloadList(rows){if(!rows.length)return '<div class="empty"><h2>No files waiting to download.</h2><p>Approved updates will appear here.</p></div>';return `<div class="section-heading"><p class="context-note">Nothing has reached OLSD yet.</p><div><span>${rows.filter(t=>ui.downloadSelection.has(t.id)).length} selected</span> · <button class="link" data-action="select-all-downloads">${rows.every(t=>ui.downloadSelection.has(t.id))?'Clear selection':'Select all '+rows.length}</button></div></div>${fileCount(rows.map(t=>t.id))>1?'<p>These tests update different parts of the catalog, so OLSD needs separate files.</p>':''}${rows.map(t=>`<article class="approval-row"><label class="approval-pick"><input type="checkbox" data-download-select="${t.id}" aria-label="Select ${e(t.title)} for download" ${ui.downloadSelection.has(t.id)?'checked':''}> Select</label><button class="entry-title" data-test="${t.id}">${e(t.title)}</button>${valuesChanged(t)}<button class="link" data-withdraw="${t.id}">Withdraw approval</button></article>`).join('')}`;}
function dateFooter(){const overdue=Date.now()-new Date(state.epicDate)>36*3600000;return `<footer class="dates">Epic checked ${fmt(state.epicDate)} (${age(state.epicDate)}) · Catalog updated ${fmt(state.olsdDate)} (${age(state.olsdDate)})${overdue?' · <strong>Epic check overdue</strong>':''}</footer>`;}
function fileCount(ids){return groupFiles(ids.map(byId).filter(t=>t&&ready(t))).length;}
function downloadButton(ids){const valid=ids.filter(id=>byId(id)&&ready(byId(id))),n=fileCount(valid);return n?`<button class="primary" data-download-ids="${valid.join(',')}">${n===1?'Download update file':'Download '+n+' files'}</button>`:'';}
function primaryForList(rows){if(ui.walkResult)return '';if(ui.query)return '';if(ui.tab==='approve'){const ids=rows.filter(t=>ui.approvalSelection.has(t.id)).map(t=>t.id),all=ids.length===rows.length;if(ids.length)return `<div class="save-actions"><button class="primary" data-action="approve-all">${all&&ids.length>1?'Approve all '+ids.length:'Approve '+ids.length+' selected '+(ids.length===1?'test':'tests')}</button><button data-action="send-back-selected">${ids.length===1?'Send selected test back to review':all?'Send all '+ids.length+' back to review':'Send '+ids.length+' back to review'}</button></div>`;return downloadButton(ui.justApproved);}if(ui.tab==='download'){const ids=rows.filter(t=>ui.downloadSelection.has(t.id)).map(t=>t.id),all=ids.length===rows.length;return ids.length?`<div class="save-actions">${downloadButton(ids)}<button data-action="withdraw-selected">${ids.length===1?'Withdraw approval for selected test':all?'Withdraw all '+ids.length+' approvals':'Withdraw '+ids.length+' selected approvals'}</button></div>`:'';}return '';}
function saveResult(){if(ui.walkResult){const w=ui.walkResult,waiting=state.tests.some(w.kind==='approve'?ready:canApprove);return `<div class="walk-result">${w.count} test${w.count===1?'':'s'} ${w.kind==='approve'?'approved':'saved'}.${waiting?` <button class="primary" data-tab="${w.kind==='approve'?'download':'approve'}">Go to ${w.kind==='approve'?'To download':'To approve'}</button>`:''}</div>`;}return ui.saveResult?`<div class="save-result" role="note">${ui.saveResult.count} saved${ui.undo?' · <button class="link" data-action="undo-save">Undo</button>':''}${ui.saveResult.approve?' <button class="primary" data-tab="approve">Go to To approve</button>':''}</div>`:'';}
function unsavedBar(onTest=false){const ids=unsavedIds(),n=ids.reduce((a,id)=>a+changesFor(staged.get(id)).length,0);if(!n)return '';const left=onTest?questionKeys(working).filter(k=>!working.decisions[k]?.choice).length:0,next=onTest?nextTarget():null,walk=onTest&&ui.walk?.kind==='review',action=walk&&!left?(walkNext()?'save-next':'save-finish'):'save',text=action==='save-next'?'Save and next':action==='save-finish'?'Save and finish':onTest?'Save':'Save '+n,extras=`${action!=='save'?'<button data-action="save">Save</button>':''}${!walk&&onTest&&next&&!left?'<button data-action="save-next">Save and next</button>':''}${onTest?'<button data-action="save-exit">Save and exit</button>':''}<button class="link" data-action="see-changes">See changes</button><button class="link" data-action="discard">Discard</button>`;return `<div class="save-bar ${ui.more?'more-open':''}"><div class="bar-context"><strong>${n} unsaved choice${n===1?'':'s'}</strong>${left?` · ${left} more to choose on this test`:''}</div><div class="save-actions"><button class="primary" data-action="${action}">${text}</button><button class="save-more-toggle" data-action="save-more" aria-expanded="${ui.more}">More</button><div class="save-secondary">${extras}</div></div></div>`;}
function bulkBar(){const keys=[...ui.selected],eligible=keys.filter(x=>BULK_KEYS.includes(x.split('|')[1])),n=eligible.length,tests=new Set(keys.map(x=>x.split('|')[0])).size,affected=new Set(eligible.map(x=>x.split('|')[0])).size,what=n===affected?`${n}`:`${n} changes on ${affected} ${affected===1?'test':'tests'}`,unsaved=unsavedIds().reduce((a,id)=>a+changesFor(staged.get(id)).length,0);return tests?`<div class="save-bar selection-bar ${ui.more?'more-open':''}"><div class="bar-context">${tests} test${tests===1?'':'s'} selected${unsaved?` · ${unsaved} unsaved choice${unsaved===1?'':'s'}`:''}</div><div class="save-actions">${n?`<button class="primary" data-action="bulk-epic">Use Epic for ${what}</button>`:'<button class="primary" data-action="walk">Review one by one</button>'}<button class="save-more-toggle" data-action="save-more" aria-expanded="${ui.more}">More</button><div class="save-secondary">${n?'<button data-action="bulk-olsd">Keep what is in the OLSD</button><button data-action="bulk-defer">Decide later</button><button class="link" data-action="walk">Review one by one</button>':''}${unsaved?'<button data-action="save">Save</button>':''}<button class="link" data-action="clear-selection">Clear</button></div></div></div>`:'';}
function importNext(){if(!ui.downloaded.length)return '';return `<div class="import-next"><h2>Next, import ${ui.downloaded.length===1?'this file':'these files'} into OLSD.</h2><p>These tests will show as done when a later OLSD snapshot matches.</p><p class="sample-warning">These are demo files. Do not import sample data into a live catalog.</p>${ui.downloaded.map(x=>`<div>${e(x.fileName)} <button class="link" data-redownload="${x.id}">Download again</button></div>`).join('')}</div>`;}
function overdueNotice(){return Date.now()-new Date(state.epicDate)>36*3600000?'<p class="overdue-note">The Epic check is overdue. The last check was '+fmt(state.epicDate)+'.</p>':'';}
function worklistView(){const c=stageCounts(),rows=baseRows(),blocked=state.tests.filter(t=>t.blocked).length,later=state.tests.filter(deferred).length;return `<div class="page-heading"><h1>Catalog worklist</h1>${primaryForList(rows)}</div>${overdueNotice()}<label class="search-label"><span class="sr-only">Search all tests</span><input id="search" type="search" placeholder="Search all tests" value="${e(ui.query)}"></label><div class="tabs">${[['review','To review',c.review],['approve','To approve',c.approve],['download','To download',c.download],['all','All tests',c.all]].map(([v,l,n])=>`<button data-tab="${v}" class="tab ${!ui.query&&ui.tab===v?'active':''}" aria-pressed="${!ui.query&&ui.tab===v}">${l} <span>${n}</span></button>`).join('')}</div><div class="list-controls">${ui.query?`<span>${rows.length} ${rows.length===1?'result':'results'} across all tests</span>`:['review','approve'].includes(ui.tab)&&rows.length?'<button data-action="walk">Review one by one</button>':'<span></span>'}<div><details class="filter"><summary>Filter${ui.lab!=='all'?' · '+e(ui.lab):''}</summary><label for="lab-filter">Lab section</label><select id="lab-filter"><option value="all">All lab sections</option>${[...new Set(state.tests.map(t=>t.section))].map(s=>`<option ${ui.lab===s?'selected':''}>${e(s)}</option>`).join('')}</select></details>${ui.tab==='all'&&!ui.query?`<label class="all-filter-label">Show <select id="all-filter">${[['all','All tests'],['kept','Kept wording'],['later','Set aside'],['waiting','Waiting on a lab name'],['downloaded','Downloaded'],['done','Done']].map(([v,l])=>`<option value="${v}" ${ui.allFilter===v?'selected':''}>${l}</option>`).join('')}</select></label>`:''}</div></div>${ui.lab!=='all'?`<p class="filter-count">${rows.length} of ${ui.query?state.tests.filter(t=>`${t.title} ${t.number} ${t.id}`.toLowerCase().includes(ui.query.toLowerCase())).length:c[ui.tab]} tests</p>`:''}${saveResult()}${importNext()}${ui.query||ui.tab==='all'?rows.slice(0,ui.limit).map(plainRow).join('')+(rows.length>ui.limit?'<button class="link load-more" data-action="load-more">Load more tests</button>':''):ui.tab==='review'?reviewList(rows):ui.tab==='approve'?approveList(rows):downloadList(rows)}${ui.tab==='review'&&!ui.query?`<p class="quiet-line">${state.role==='editor'&&blocked?`<button class="link" data-all-filter="waiting">${blocked} test${blocked===1?'':'s'} waiting on a lab name</button>`:''}${blocked&&later?' · ':''}${later?`<button class="link" data-all-filter="later">${later} set aside for later</button>`:''}</p>`:''}${ui.selected.size?bulkBar():unsavedBar()}${dateFooter()}`;}
function nextTarget(){if(!working)return null;const copy=display(byId(working.id));if(activeKeys(copy).length)return {id:working.id};const queue=ui.queue,at=queue.indexOf(working.id);const candidates=ui.walk?queue.slice(at+1):[...queue.slice(at+1),...queue.slice(0,Math.max(0,at))];const next=candidates.find(id=>id!==working.id&&byId(id)&&(ui.queueMode==='review'?toReview(byId(id)):true));return next?{id:next}:null;}
function questionKeys(t){const saved=byId(t.id),open=activeKeys(saved);return FIELDS.map(f=>f.key).filter(k=>open.includes(k)||ui.reopened.has(t.id+':'+k)||(saved.pending[k]&&staged.has(t.id)&&t.decisions[k]?.choice!==saved.decisions[k]?.choice));}
function questionKey(t){const keys=questionKeys(t);return keys.find(k=>!t.decisions[k]?.choice)||((keys.length>1||pendingKeys(byId(t.id)).length>1)?null:keys[0])||null;}
function questionHeading(t,k){const p=byId(t.id).pending[k];return p?.source==='OLSD'?`The catalog's ${label(k).toLowerCase()} changed.`:p?.source==='Catalog'?`Review this saved ${label(k).toLowerCase()} change.`:p?.source==='Lab mapping'?'The lab name is ready.':ui.reopened.has(t.id+':'+k)?`Change your saved ${label(k).toLowerCase()} choice.`:`Epic changed ${k==='name'?'the test name':k==='labs'?'the performing laboratories':label(k).toLowerCase()}.`;}
function sourceContext(t,k){const p=byId(t.id).pending[k];return p?.source==='OLSD'?`<div class="old-new source-context"><div><small>Was</small><div class="value">${e(p.before)}</div></div><div><small>Now</small><div class="value">${e(p.after)}</div></div></div>`:'';}
function changeChoice(k){if(!working||working.blocked)return;ui.reopened.add(working.id+':'+k);ui.more=false;render();document.querySelector(`[data-question="${k}"] button`)?.focus({preventScroll:true});document.querySelector(`[data-question="${k}"] h2`)?.scrollIntoView({block:'nearest'});}
function savedChoices(t){const keys=FIELDS.map(f=>f.key).filter(k=>t.decisions[k]?.choice&&t.decisions[k].choice!=='defer');if(!keys.length)return '';return `<section class="saved-choices"><h2>Your saved choices</h2>${keys.map(k=>`<article data-saved-choice="${k}"><div class="section-heading"><h3>${e(label(k))}</h3><button data-change-choice="${k}">Change</button></div><div class="old-new"><div><small>In OLSD now</small><div class="value">${e(t.olsd[k])||'Empty'}</div></div><div><small>${equal(t.proposed[k],t.olsd[k],k)?'Kept':'Will say after import'}</small><div class="value">${e(t.proposed[k])||'Empty'}</div></div></div>${t.decisions[k].note?`<p>Note: ${e(t.decisions[k].note)}</p>`:''}</article>`).join('')}</section>`;}
function setAsideChoices(t){const keys=pendingKeys(t).filter(k=>t.decisions[k]?.choice==='defer');return keys.length?`<section class="set-aside"><h2>Set aside</h2>${keys.map(k=>`<article data-set-aside="${k}"><div class="section-heading"><h3>${e(label(k))}</h3><button data-change-choice="${k}">Change</button></div><p>Epic: <span class="value">${e(t.epic[k])||'No corresponding Epic value'}</span></p>${t.decisions[k].note?`<p>Note: ${e(t.decisions[k].note)}</p>`:''}</article>`).join('')}</section>`:'';}
function originLabel(){return ui.query?'Search results':({review:'To review',approve:'To approve',download:'To download',all:'All tests'}[ui.tab]||'Worklist');}
function testArgs(id){return {id,from:ui.tab,...(ui.query?{q:ui.query}:{})};}
function walkNext(){if(!working)return null;return ui.queue.slice(ui.queue.indexOf(working.id)+1).find(id=>byId(id)&&(ui.walk?.kind==='approve'?canApprove(byId(id)):toReview(byId(id))))||null;}
function finishWalk(){const w=ui.walk;ui.walkResult={kind:w.kind,count:w.kind==='approve'?[...w.done].filter(id=>approved(byId(id))).length:w.done.size};ui.walk=null;ui.justApproved=[];ui.saveResult=null;ui.selected.clear();ui.approvalSelection.clear();history.pushState({},'',route('worklist',{tab:ui.tab,q:ui.query}));loadRoute(location.hash);}
function startWalk(){const order=displayRows(),picked=ui.tab==='approve'?ui.approvalSelection:new Set([...ui.selected].map(x=>x.split('|')[0])),list=picked.size?order.filter(t=>picked.has(t.id)):order;if(!list.length)return;ui.scrollY=window.scrollY;ui.queue=list.map(t=>t.id);ui.queueMode=ui.tab==='approve'?'approve':'review';ui.walk={kind:ui.queueMode,done:new Set()};ui.walkResult=null;go('test',testArgs(list[0].id));}
function approveAndNext(){if(!working||dirtyNow())return;const id=working.id,next=walkNext();if(!canApprove(byId(id)))return;approveIds([id]);ui.walk.done.add(id);if(next){history.pushState({},'',route('test',testArgs(next)));loadRoute(location.hash);}else finishWalk();}
function choiceCards(t,k,multi=false){const current=questionKey(t)===k,key=n=>current?`<span class="shortcut">${n}</span>`:'';const d=t.decisions[k],old=t.olsd[k],next=t.epic[k],ep=diffPair(old,next),showCustom=ui.edits.has(t.id+':'+k)||d?.choice==='custom';return `<section class="question" data-question="${k}"><h2>${questionHeading(t,k)} What should the catalog say?</h2>${sourceContext(t,k)}${next!=null?`<button class="answer-card ${d?.choice==='epic'?'selected':''}" data-answer="${k}:epic" aria-pressed="${d?.choice==='epic'}"><strong>Use Epic’s version ${key(1)}</strong><span class="value">${ep.after}</span></button>`:''}<button class="answer-card ${d?.choice==='olsd'?'selected':''}" data-answer="${k}:olsd" aria-pressed="${d?.choice==='olsd'}"><strong>Keep what is in the OLSD ${key(2)}</strong><span class="value">${e(old)||'Empty'}</span></button>${savedWording(byId(t.id),k)?`<button class="answer-card ${d?.choice==='custom'&&equal(t.proposed[k],byId(t.id).proposed[k],k)?'selected':''}" data-answer="${k}:saved" aria-pressed="${d?.choice==='custom'&&equal(t.proposed[k],byId(t.id).proposed[k],k)}"><strong>Keep my saved wording</strong><span class="value">${e(byId(t.id).proposed[k])}</span></button>`:''}<div class="question-options">${multi?(d?.choice==='defer'?'<span class="status">Set aside</span>':''):`<button class="link ${d?.choice==='defer'?'selected':''}" data-answer="${k}:defer">Decide later</button>`}${['name','conditions'].includes(k)?`<button class="link" data-write="${k}">Write my own</button>`:''}<button class="link" data-toggle-note="${k}">Add a note</button></div>${showCustom&&['name','conditions'].includes(k)?`<label class="edit-label">What the catalog should say<textarea id="edit-${k}" data-edit="${k}">${e(t.proposed[k])}</textarea></label>`:''}${ui.notes.has(t.id+':'+k)||d?.note?`<label class="edit-label">Note (optional)<input id="note-${k}" data-note="${k}" value="${e(d?.note||'')}"></label>`:''}${t.pending[k]?.previous?previousChoice(t,k):''}</section>`;}
function previousChoice(t,k){const d=t.pending[k].previous;return `<p class="previous-choice">${d.choice==='defer'?'You set this aside':'You kept “'+e(t.proposed[k])+'”'} on ${fmt(d.at)}${d.note?' · '+e(d.note):''}. Epic then said “${e(d.epic)}”; Epic now says “${e(t.epic[k])}”.</p>`;}
function entryEditor(t,k){if(k==='categories'){const base=(t.epic.categories||'').split(';').filter(Boolean),chosen=t.proposed.categories.split(';').filter(Boolean);return `<div class="category-edit"><p>Added from the lab mapping: ${base.map(e).join('; ')||'None'}.</p><details data-detail="${t.id}:categories" ${ui.details.has(t.id+':categories')?'open':''}><summary>Additional categories</summary>${CATEGORIES.filter(c=>!base.includes(c)).map(c=>`<label><input type="checkbox" data-category="${e(c)}" ${chosen.includes(c)?'checked':''}> ${e(c)}</label>`).join('')}</details><details><summary>Removing a category already in OLSD</summary><p>An upload cannot remove an existing category. An administrator must arrange that separately.</p></details></div>`;}if(k==='labs')return `<p>Laboratory names are managed centrally. <button class="link" data-blocker="${t.id}">Open lab mapping</button></p>`;return `<label class="edit-label"><span class="sr-only">${e(label(k))}</span><textarea id="edit-${k}" data-edit="${k}">${e(t.proposed[k])}</textarea></label>`;}
function entryContent(t,omit){return `<section class="catalog-entry"><h2>In OLSD now</h2>${FIELDS.filter(f=>Array.isArray(omit)?!omit.includes(f.key):f.key!==omit).map(f=>`<div class="entry-field" data-entry-field="${f.key}"><div class="section-heading"><h3>${e(f.label)}</h3><button class="link" data-edit-field="${f.key}">Edit</button></div>${ui.edits.has(t.id+':'+f.key)?entryEditor(t,f.key):`<div class="value">${e(t.olsd[f.key])||'Not recorded'}</div>`}</div>`).join('')}</section>`;}
function decisionHistory(t){return `<details class="history"><summary>History</summary>${t.history.slice().reverse().map(h=>`<article><strong>${e(h.action)}${h.field?' · '+e(label(h.field)):''}</strong><p>${fmt(h.at)} · ${e(h.actor)}</p>${h.choice?`<p>${e(choiceLabel(h.choice))}${h.note?' · '+e(h.note):''}</p>`:''}${h.before!==undefined?`<p>Before: ${e(h.before)}<br>After: ${e(h.after)}</p>`:''}</article>`).join('')||'<p>No saved actions yet.</p>'}${t.approval?`<article><strong>Approval</strong><p>${e(t.approval.by)} · ${fmt(t.approval.at)}</p><p>Catalog values dated ${fmt(t.approval.basis.olsdDate)}; Epic values dated ${fmt(t.approval.basis.epicDate)}.</p></article>`:''}</details>`;}
function blockerCard(t){return `<section class="blocker"><h2>Waiting on a lab name</h2><p>${e(t.section)} does not have a public performing-laboratory name yet. A catalog administrator needs to choose it.</p><div class="row"><button class="${state.role==='admin'?'primary':'link'}" data-blocker="${t.id}">${state.role==='admin'?'Choose the lab name':'View the mapping needed'}</button>${state.role==='editor'?`<button class="link" data-request="${t.id}">Request help</button>`:''}</div>${t.requests.length?'<p>Help request noted in this demo. No message was sent.</p>':''}</section>`;}
function testView(){const t=working,keys=questionKeys(t),k=keys[0]||null,multi=keys.length>1||pendingKeys(byId(t.id)).length>1,undecided=keys.filter(q=>!t.decisions[q]?.choice).length,hasUnsaved=changesFor(t).length>0,saved=byId(t.id),awaiting=!hasUnsaved&&canApprove(saved),readySaved=!hasUnsaved&&approved(saved)&&!confirmed(saved),position=ui.queue.indexOf(t.id),prev=ui.queue.slice(0,Math.max(0,position)).reverse().find(id=>byId(id)),next=ui.queue.slice(position+1).find(id=>byId(id));return `<div class="test-nav"><button class="link" data-action="back-worklist">‹ ${e(originLabel())}</button><div>${position>=0?`${position+1} of ${ui.queue.length}`:''}<button ${prev?`data-test="${prev}"`:'disabled'} aria-label="Previous test" title="${prev?'Previous test':'First test in this sequence'}">‹</button><button ${next?`data-test="${next}"`:'disabled'} aria-label="Next test" title="${next?'Next test':'Last test in this sequence'}">›</button></div></div><div class="page-heading"><div><h1>${e(t.title)}</h1><p class="muted">${e(t.number)} · ${e(t.section)}</p></div>${plainBadge(t)}</div>${t.blocked?blockerCard(t):keys.length?`${multi?`<p class="question-count"><strong>${keys.length} changes on this test</strong> · ${keys.length-undecided} of ${keys.length} chosen</p>`:''}${keys.map(q=>choiceCards(t,q,multi)).join('')}${multi&&undecided?`<p class="defer-rest"><button class="link" data-action="defer-rest">Decide later</button> <span class="muted">Sets aside ${undecided===keys.length?'this test':'the changes you haven’t chosen yet'}.</span></p>`:''}`:''}${!t.blocked&&!k&&awaiting?`<section class="saved-review"><h2>Ready for approval</h2>${valuesChanged(saved,changedKeys(saved),true)}<p>Approving doesn’t change OLSD. You’ll download a file and import it.</p>${ui.walk?.kind==='approve'?`<button class="primary" data-action="approve-next">${walkNext()?'Approve and next':'Approve and finish'}</button>`:`<button class="primary" data-approve="${t.id}">Approve</button>`}<button data-send-back="${t.id}">Send back to review</button></section>`:''}${readySaved?`<section class="saved-review"><h2>Approved</h2>${valuesChanged(saved,changedKeys(saved),true)}${ui.walk?.kind==='approve'?'':downloadButton([saved.id])}<button data-withdraw="${t.id}">Withdraw approval</button></section>`:''}${!t.blocked&&!k&&!awaiting&&!readySaved&&!hasUnsaved&&retained(saved)?'<p class="context-note">Your choice is saved. The catalog stays as it is; no approval or download is needed.</p>':''}${deferred(saved)&&!hasUnsaved?`<p class="context-note">Set aside for later${Object.values(saved.decisions).find(d=>d.choice==='defer')?.note?': '+e(Object.values(saved.decisions).find(d=>d.choice==='defer').note):''}. It will return if Epic changes it again. <button class="link" data-action="resume-review">Review now</button></p>`:''}${approved(saved)&&(hasUnsaved||[...ui.reopened].some(x=>x.startsWith(saved.id+':')))?'<p class="approval-warning">Saving a changed choice will withdraw this test’s approval.</p>':''}${ui.walk&&!hasUnsaved&&!walkNext()&&!(ui.walk.kind==='approve'?canApprove(saved):keys.length)?'<p><button data-action="finish-walk">Finish</button></p>':''}${savedChoices(saved)}${setAsideChoices(saved)}${importNext()}${entryContent(t,keys.length?keys:(awaiting||readySaved?changedKeys(saved):null))}${decisionHistory(t)}${unsavedBar(true)}${dateFooter()}`;}
function groupFiles(tests){const groups=new Map();for(const t of tests){const fields=included(t),key=fields.join('|');if(!groups.has(key))groups.set(key,{fields,ids:[]});groups.get(key).ids.push(t.id);}return [...groups.values()];}
function deliver(ids){if(dirtyNow()){toast('Save or discard your choices before downloading.');return;}const tests=ids.map(byId).filter(t=>t&&ready(t));if(!tests.length)return;const plan={id:Date.now().toString(36),tests:clone(tests),groups:groupFiles(tests)};ui.downloaded=[];for(let i=0;i<plan.groups.length;i++){const g=plan.groups[i];downloadExcel(plan,i);const record={id:plan.id+'-'+i,at:stamp(),fileName:fileName(plan,i),fields:clone(g.fields),tests:clone(plan.tests.filter(t=>g.ids.includes(t.id))),check:null};state.exports.push(record);ui.downloaded.push(record);for(const id of g.ids)ui.downloadSelection.delete(id);for(const t of record.tests)event(byId(t.id),'Downloaded update file',{file:record.fileName});}ui.undo=null;ui.saveResult=null;ui.justApproved=[];persist();refreshWorking();render();focusNext();}
function redownload(id){const x=state.exports.find(r=>r.id===id);if(!x)return;downloadExcel({id:x.id,fileNames:[x.fileName],tests:x.tests,groups:[{fields:x.fields,ids:x.tests.map(t=>t.id)}]},0);toast('File downloaded again.');}
function downloadsView(){return `<div class="page-heading"><h1>Downloads</h1></div>${importNext()}${state.exports.length?[...state.exports].reverse().map(x=>`<article class="download-record"><div class="section-heading"><h2>${e(x.fileName)}</h2><button class="link" data-redownload="${x.id}">Download again</button></div><p>${fmt(x.at)} · ${x.tests.map(t=>e(t.title)).join('; ')}</p>${x.check?`<p>${x.check.allMatch?'Done · matched the catalog on '+fmt(x.check.at):'Returned to To review · the catalog does not match this file.'}</p>${x.check.rows.map(r=>`<p>${e(r.name)}: ${r.details.map(e).join('; ')}</p>`).join('')}`:'<p>Downloaded, import into OLSD. Nothing has reached OLSD yet.</p>'}${state.role==='admin'?`<details class="admin-comparison"><summary>Demo: check a later OLSD snapshot</summary><button data-reconcile="${x.id}:match">Load matching example</button><button data-reconcile="${x.id}:partial">Load different example</button></details>`:''}<details><summary>File contents</summary>${x.tests.map(t=>`<h3>${e(t.title)}</h3>${valuesChanged(t,x.fields)}`).join('')}</details></article>`).join(''):'<p>No files have been downloaded.</p>'}<p class="context-note">A matching snapshot confirms the values observed on that date. It does not prove real-time publication.</p>`;}
function historyFor(t){return decisionHistory(t);}
function mappingView(){const m=state.mapping;return `<div class="page-heading"><h1>Lab mappings</h1></div>${mappingReturn?`<button class="link" data-action="mapping-back">‹ Back to ${e(byId(mappingReturn)?.title||'test')}</button>`:''}${state.role!=='admin'?'<p>Only an administrator can choose the public laboratory name. Use Request help on the test.</p>':''}<p>Epic lists <strong>KH CHEMISTRY</strong>. Choose the name people should see in the catalog.</p><div class="mapping-form"><label>Public lab name<input id="map-name" value="${e(m.name)}" placeholder="Chemistry Laboratory KOP Hospital" ${state.role!=='admin'?'disabled':''}></label><label>Search category<select id="map-category" ${state.role!=='admin'?'disabled':''}>${CATEGORIES.map(c=>`<option ${m.category===c?'selected':''}>${e(c)}</option>`).join('')}</select></label>${state.role==='admin'?'<button class="primary" data-action="save-mapping">Save lab name</button>':''}</div><h2>Current lab names</h2><div class="mapping-list"><p>UC CHEMISTRY → Chemistry Laboratory Main Hospital</p><p>UC HEMATOLOGY → Hematology Laboratory Main Hospital</p>${m.name?`<p>KH CHEMISTRY → ${e(m.name)}</p>`:''}</div>`;}
function saveMapping(){if(state.role!=='admin')return;const name=document.getElementById('map-name').value.trim(),category=document.getElementById('map-category').value;if(!name){toast('Enter the public lab name.');return;}state.mapping={...state.mapping,name,category};for(const t of state.tests.filter(t=>t.section===state.mapping.section)){const old=t.epic.labs;t.blocked=false;t.epic.labs=name;t.epic.categories=category;t.pending.labs={source:'Lab mapping',before:old,after:name,at:stamp()};if(t.approval)t.approval.outdated=true;event(t,'Lab name added',{field:'labs',before:old,after:name});}ui.undo=null;persist();render();toast('Lab name saved. The affected tests are ready to review.');}
function requestHelp(id){const t=byId(id);showModal('Request help',`<p>A catalog administrator needs to choose the public lab name for ${e(t.section)}.</p><p>This demo can note the request. No message will be sent.</p>`,[['Cancel',()=>closeModal()],['Note request',()=>{t.requests.push({at:stamp(),by:actor()});event(t,'Help requested',{section:t.section});persist();closeModal();refreshWorking();render();toast('Request noted in this demo. No message was sent.');},'primary']]);}
function snapshotModal(){if(state.role!=='admin')return;guard(()=>showModal('Update OLSD snapshot','<p>Load a newer sample snapshot. Saved wording is preserved, and unexpected catalog changes return to To review.</p>',[['Cancel',()=>closeModal()],['Load example snapshot',()=>{applySnapshot({'785258':{conditions:'Illustrative newer OLSD wording from the uploaded export.'}});ui.undo=null;ui.saveResult=null;closeModal();refreshWorking();render();toast('Catalog updated. Unexpected changes are in To review.');},'primary']]));}
function reconcile(id,mode){if(state.role!=='admin')return;guard(()=>{const x=state.exports.find(r=>r.id===id);if(!x)return;const updates={};for(const [i,t] of x.tests.entries()){updates[t.id]={};for(const k of x.fields){let value=t.proposed[k];if(mode==='partial'&&i===0){if(k==='categories')value+=';Legacy category awaiting cleanup';else if(k===x.fields[0])value='Sample different catalog value';}updates[t.id][k]=value;}}applySnapshot(updates);ui.undo=null;ui.downloaded=[];refreshWorking();render();toast(mode==='match'?'These downloaded values match the later catalog.':'The catalog differs. Review the changes in To review.');});}
function checkEpic(){guard(()=>{const updates={};for(const t of state.tests)for(const f of FIELDS){const d=t.decisions[f.key];if(['olsd','custom','defer'].includes(d?.choice)&&t.epic[f.key]!=null){updates[t.id]??={};updates[t.id][f.key]=t.epic[f.key]+' · new Epic version';}}if(!Object.keys(updates).length)updates['demo-tsh']={name:byId('demo-tsh').epic.name+' · new Epic version'};applySource('Epic',updates);ui.undo=null;ui.saveResult=null;refreshWorking();render();toast('Epic checked. New changes are in To review.');});}
function focusSelector(el=document.activeElement){if(!el?.matches)return null;if(el.id)return '#'+CSS.escape(el.id);for(const key of ['data-tab','data-inline','data-select','data-select-test','data-approve-select','data-download-select','data-answer','data-change-choice','data-test','data-approve','data-action','data-write','data-edit-field','data-category','data-nav'])if(el.hasAttribute(key))return `[${key}="${CSS.escape(el.getAttribute(key))}"]`;return null;}
function focusBack(selector){if(selector)document.querySelector(selector)?.focus({preventScroll:true});}
function render(focus=focusSelector()){document.getElementById('main-nav').innerHTML=`<button class="nav-link ${view==='worklist'||view==='test'?'active':''}" data-nav="worklist">Worklist</button><button class="nav-link ${view==='downloads'?'active':''}" data-nav="downloads">Downloads</button>${state.role==='admin'?'<button class="nav-link" data-nav="mapping">Lab mappings</button><button class="nav-link" data-action="snapshot">Update OLSD snapshot</button>':''}`;document.getElementById('role').value=state.role;document.getElementById('content').innerHTML=view==='test'?testView():view==='downloads'?downloadsView():view==='mapping'?mappingView():worklistView();focusBack(focus);}
let toastTimer=null;function toast(text){clearTimeout(toastTimer);document.getElementById('toast').innerHTML=`<div class="toast">${e(text)}</div>`;toastTimer=setTimeout(()=>document.getElementById('toast').innerHTML='',4000);}
let modal={opener:null,cancel:null};
function showModal(title,body,buttons,options={}){const opener=focusSelector();for(const el of document.querySelectorAll('.topbar,.sample-strip,#content'))el.inert=true;modal={opener,cancel:options.cancel||null};document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${e(title)}</h2>${body}<div class="modal-actions">${buttons.map(([text,fn,cls],i)=>`<button class="${cls||''}" data-modal-button="${i}">${e(text)}</button>`).join('')}</div></section></div>`;document.querySelectorAll('[data-modal-button]').forEach(b=>b.onclick=()=>buttons[+b.dataset.modalButton][1]());document.querySelector('#modal-root button')?.focus();}
function closeModal(cancel=false){const old=modal;document.getElementById('modal-root').innerHTML='';for(const el of document.querySelectorAll('.topbar,.sample-strip,#content'))el.inert=false;modal={opener:null,cancel:null};if(cancel)old.cancel?.();focusBack(old.opener);}
function guard(next,cancel=()=>{}){if(!dirtyNow()){next();return;}showModal('Unsaved choices','<p>Save your choices or discard them before leaving.</p>',[['Stay',()=>closeModal(true)],['Discard',()=>{resetWorking();closeModal();next();}],['Save and continue',()=>{saveAll();if(dirtyNow()){closeModal();render();document.querySelector('textarea')?.focus();return;}closeModal();next();},'primary']],{cancel:()=>{document.getElementById('role').value=state.role;cancel();}});}
function showChanges(){
 const body=unsavedIds().map(id=>{
  const t=staged.get(id);
  const sections=changesFor(t).map(f=>{
   const rows=f.changes.map(c=>{const d=diffPair(c.before,c.after);return `${c.label===f.label?'':'<p>'+e(c.label)+'</p>'}<div class="old-new"><div><small>Before your edits</small><div class="value">${d.before||'Empty'}</div></div><div><small>Your unsaved version</small><div class="value">${d.after||'Empty'}</div></div></div>`;}).join('');
   return `<section data-unsaved-field="${f.key}"><h4>${e(f.label)}</h4>${rows}</section>`;
  }).join('');
  return `<h3>${e(t.title)}</h3>${sections}`;
 }).join('');
 showModal('Unsaved changes',body,[['Continue choosing',()=>closeModal()]]);
}
function bulkChoose(choice){for(const key of ui.selected){const [id,k]=key.split('|');if(!['name','labs'].includes(k)||byId(id).blocked||!byId(id).pending[k])continue;const t=editCopy(id);choose(t,k,choice);syncInclude(t);}ui.selected.clear();ui.saveResult=null;dirtyNow();render();}
function saveWithNavigation(mode='stay'){const id=working?.id,next=mode==='next'?nextTarget():null;const saved=saveAll();if(!saved.length)return;ui.more=false;ui.question=null;if(mode==='finish'){finishWalk();return;}if(mode==='exit'){ui.walk=null;history.pushState({},'',route('worklist',{tab:ui.tab,q:ui.query}));loadRoute(location.hash);return;}if(mode==='next'&&next&&next.id!==id){history.pushState({},'',route('test',testArgs(next.id)));loadRoute(location.hash);return;}refreshWorking();render();focusNext();}
function chooseInline(id,k,c){if(!['name','labs'].includes(k)||byId(id).blocked||!byId(id).pending[k])return;const t=editCopy(id);choose(t,k,c);syncInclude(t);ui.saveResult=null;dirtyNow();refreshWorking();render(`[data-inline="${id}|${k}|${c}"]`);}
function chooseAnswer(k,c){if(!working||working.blocked||!byId(working.id).pending[k]&&!ui.reopened.has(working.id+':'+k))return;const t=editCopy(working.id);ui.question=k;choose(t,k,c);syncInclude(t);working=t;ui.saveResult=null;dirtyNow();render(`[data-answer="${k}:${c}"]`);}
function editField(k){const t=editCopy(working.id);ui.edits.add(t.id+':'+k);working=t;render(`[data-edit-field="${k}"]`);document.getElementById('edit-'+k)?.focus();}
function writeOwn(k){if(!['name','conditions'].includes(k))return;const t=editCopy(working.id);ui.question=k;choose(t,k,'custom');syncInclude(t);working=t;dirtyNow();render();document.getElementById('edit-'+k)?.focus();}
function approveIds(ids){if(dirtyNow()){toast('Save your choices before approving.');return;}const done=[];for(const id of ids){const t=byId(id);if(t&&canApprove(t)){approveRecord(t);done.push(id);}}ui.undo=null;ui.saveResult=null;ui.justApproved=done;for(const id of done)ui.approvalSelection.delete(id);ui.downloaded=[];persist();refreshWorking();render();focusNext();}
function sendBackIds(ids){for(const id of ids){const t=byId(id);if(!t||!canApprove(t))continue;for(const k of changedKeys(t)){t.pending[k]={source:'Catalog',before:t.olsd[k],after:t.proposed[k],at:stamp()};delete t.decisions[k];}t.approval=null;t.draft=true;event(t,'Sent back to review');}ui.undo=null;ui.approvalSelection.clear();ui.justApproved=[];persist();refreshWorking();render();}
function sendBack(id){sendBackIds([id]);}
function withdrawIds(ids){for(const id of ids){const t=byId(id);if(!t||!approved(t))continue;t.approval=null;t.draft=true;event(t,'Withdrew approval');}ui.undo=null;ui.downloadSelection.clear();ui.justApproved=[];persist();refreshWorking();render();}
function withdraw(id){withdrawIds([id]);}
function route(v,args={}){return '#/'+v+(Object.keys(args).length?'?'+new URLSearchParams(args):'');}
function go(v,args={}){guard(()=>{history.pushState({},'',route(v,args));loadRoute(location.hash);});}
function openTest(id){if(view==='worklist'){ui.scrollY=window.scrollY;ui.queue=displayRows().map(t=>t.id);ui.queueMode=ui.tab==='review'&&!ui.query?'review':'list';ui.walk=null;ui.walkResult=null;}go('test',testArgs(id));}
function loadRoute(hash){const wasTest=view==='test';currentHash=hash||'#/worklist';const [v,qs='']=currentHash.slice(2).split('?'),p=new URLSearchParams(qs);view=['worklist','test','downloads','mapping'].includes(v)?v:'worklist';ui.question=null;working=null;original=null;if(view==='test'){if(p.has('from'))ui.tab=p.get('from');if(p.has('q'))ui.query=p.get('q');const t=byId(p.get('id'));if(t){if(!ui.queue.includes(t.id)){ui.queueMode=p.has('from')?(ui.tab==='review'&&!ui.query?'review':'list'):toReview(t)?'review':'list';ui.queue=(p.has('from')?displayRows():toReview(t)?state.tests.filter(toReview):state.tests).map(t=>t.id);if(!ui.queue.includes(t.id))ui.queue.unshift(t.id);}working=display(t);original=clone(t);}else view='worklist';}if(view==='worklist'){ui.tab=['review','approve','download','all'].includes(p.get('tab'))?p.get('tab'):ui.tab;ui.query=p.has('q')?p.get('q'):ui.query;}dirtyNow();render(null);document.querySelector('h1')?.setAttribute('tabindex','-1');document.querySelector('h1')?.focus({preventScroll:true});window.scrollTo(0,view==='worklist'&&wasTest?(ui.scrollY||0):0);}
function updateRoute(){const hash=route(view,view==='worklist'?{tab:ui.tab,q:ui.query}:view==='test'?{id:working.id}:{});history.replaceState({},'',hash);currentHash=hash;}
function changeTab(tab,allFilter='all'){guard(()=>{if(allFilter!=='all')ui.lab='all';ui.tab=tab;ui.walk=null;ui.walkResult=null;ui.approvalSelection.clear();ui.downloadSelection.clear();ui.allFilter=allFilter;ui.saveResult=null;ui.query='';ui.limit=30;ui.selected.clear();ui.justApproved=[];ui.downloaded=[];history.pushState({},'',route('worklist',{tab}));loadRoute(location.hash);});}
function resetDemo(){guard(()=>showModal('Reset demo?','<p>This clears the sample choices, approvals, and downloads in this browser.</p>',[['Cancel',()=>closeModal()],['Reset',()=>{staged.clear();state=initial();dirty=false;working=null;original=null;ui.tab='review';ui.approvalSelection.clear();ui.downloadSelection.clear();ui.query='';ui.lab='all';ui.limit=30;ui.selected.clear();ui.edits.clear();ui.details.clear();ui.justApproved=[];ui.queue=[];ui.walk=null;ui.walkResult=null;ui.reopened.clear();ui.undo=null;ui.saveResult=null;ui.downloaded=[];persist();closeModal();history.pushState({},'','#/worklist?tab=review');loadRoute(location.hash);},'primary']]));}
function editCategory(c,checked){const apply=()=>{const t=editCopy(working.id),set=new Set(t.proposed.categories.split(';').filter(Boolean));checked?set.add(c):set.delete(c);t.proposed.categories=[...set].join(';');choose(t,'categories','custom');syncInclude(t);working=t;dirtyNow();render();};if(!checked&&working.olsd.categories.split(';').includes(c)){showModal('Remove this category from your wording?',`<p>${e(c)} already exists in OLSD. Leaving it out of a file cannot remove it from OLSD; an administrator must arrange that cleanup separately.</p>`,[['Keep category',()=>closeModal(true)],['Remove here',()=>{closeModal();apply();},'primary']],{cancel:()=>render()});}else apply();}
function focusNext(){const next=document.querySelector('.save-result [data-tab="approve"],.save-result [data-action="undo-save"],[data-approve],[data-download-ids]');if(next){next.focus({preventScroll:true});return;}const heading=document.querySelector('.import-next h2,h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
function markDirty(){dirtyNow();const active=focusSelector(),selection=document.activeElement?.selectionStart;refreshWorking();render(active);const el=document.activeElement;if(selection!=null&&el?.setSelectionRange)el.setSelectionRange(selection,selection);}
document.addEventListener('click',ev=>{const home=ev.target.closest('[data-home]');if(home&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&!ev.altKey){ev.preventDefault();changeTab('review');return;}const b=ev.target.closest('button');if(!b||b.disabled||b.dataset.modalButton!==undefined)return;
 if(b.dataset.nav){if(b.dataset.nav==='worklist')changeTab('review');else go(b.dataset.nav);return;}
 if(b.dataset.tab){changeTab(b.dataset.tab);return;}
 if(b.dataset.allFilter){changeTab('all',b.dataset.allFilter);return;}
 if(b.dataset.test){openTest(b.dataset.test);return;}
 if(b.dataset.inline){const [id,k,c]=b.dataset.inline.split('|');chooseInline(id,k,c);return;}
 if(b.dataset.selectSection){ui.saveResult=null;const g=b.dataset.selectSection,rows=baseRows().filter(t=>!t.blocked&&reviewGroup(t)===g),all=rows.every(t=>selectionKeys(t).every(k=>ui.selected.has(t.id+'|'+k)));for(const t of rows)for(const k of selectionKeys(t))all?ui.selected.delete(t.id+'|'+k):ui.selected.add(t.id+'|'+k);render(`[data-select-section="${g}"]`);return;}
 if(b.dataset.changeChoice){changeChoice(b.dataset.changeChoice);return;}
 if(b.dataset.answer){const [k,c]=b.dataset.answer.split(':');chooseAnswer(k,c);return;}
 if(b.dataset.write){writeOwn(b.dataset.write);return;}
 if(b.dataset.toggleNote){const k=b.dataset.toggleNote;ui.notes.add(working.id+':'+k);render();document.getElementById('note-'+k)?.focus();return;}
 if(b.dataset.editField){editField(b.dataset.editField);return;}
 if(b.dataset.approve){approveIds([b.dataset.approve]);return;}
 if(b.dataset.sendBack){sendBack(b.dataset.sendBack);return;}
 if(b.dataset.withdraw){withdraw(b.dataset.withdraw);return;}
 if(b.dataset.downloadIds){deliver(b.dataset.downloadIds.split(','));return;}
 if(b.dataset.redownload){redownload(b.dataset.redownload);return;}
 if(b.dataset.blocker){mappingReturn=b.dataset.blocker;go('mapping');return;}
 if(b.dataset.request){requestHelp(b.dataset.request);return;}
 if(b.dataset.reconcile){const [id,mode]=b.dataset.reconcile.split(':');reconcile(id,mode);return;}
 switch(b.dataset.action){case 'walk':startWalk();break;case 'approve-next':approveAndNext();break;case 'finish-walk':finishWalk();break;case 'save-finish':saveWithNavigation('finish');break;case 'save-more':ui.more=!ui.more;render();break;case 'defer-rest':{const t=editCopy(working.id);for(const k of questionKeys(t))if(!t.decisions[k]?.choice)choose(t,k,'defer');syncInclude(t);working=t;dirtyNow();render();break;}case 'resume-review':{const t=editCopy(working.id);for(const [key,d] of Object.entries(t.decisions))if(d.choice==='defer')delete t.decisions[key];working=t;ui.question=null;dirtyNow();render();break;}case 'back-worklist':go('worklist',{tab:ui.tab,q:ui.query});break;case 'save':saveWithNavigation('stay');break;case 'save-next':saveWithNavigation('next');break;case 'save-exit':saveWithNavigation('exit');break;case 'see-changes':showChanges();break;case 'discard':resetWorking();break;case 'undo-save':undoSave();break;case 'bulk-epic':bulkChoose('epic');break;case 'bulk-olsd':bulkChoose('olsd');break;case 'bulk-defer':bulkChoose('defer');break;case 'clear-selection':ui.selected.clear();render();break;case 'load-more':ui.limit+=30;render();break;case 'select-all-approvals':{const rows=baseRows().filter(canApprove),all=rows.every(t=>ui.approvalSelection.has(t.id));ui.approvalSelection.clear();if(!all)for(const t of rows)ui.approvalSelection.add(t.id);render('[data-action="select-all-approvals"]');break;}case 'select-all-downloads':{const rows=baseRows().filter(ready),all=rows.every(t=>ui.downloadSelection.has(t.id));ui.downloadSelection.clear();if(!all)for(const t of rows)ui.downloadSelection.add(t.id);render('[data-action="select-all-downloads"]');break;}case 'withdraw-selected':withdrawIds(baseRows().filter(t=>ready(t)&&ui.downloadSelection.has(t.id)).map(t=>t.id));break;case 'approve-all':approveIds(baseRows().filter(t=>canApprove(t)&&ui.approvalSelection.has(t.id)).map(t=>t.id));break;case 'send-back-selected':sendBackIds(baseRows().filter(t=>canApprove(t)&&ui.approvalSelection.has(t.id)).map(t=>t.id));break;case 'save-mapping':saveMapping();break;case 'mapping-back':if(mappingReturn)openTest(mappingReturn);else changeTab('review');break;case 'snapshot':snapshotModal();break;case 'check-epic':checkEpic();break;case 'reset':resetDemo();break;}
});
document.addEventListener('input',ev=>{const n=ev.target;if(n.id==='search'){const caret=n.selectionStart;ui.query=n.value;ui.selected.clear();ui.approvalSelection.clear();ui.downloadSelection.clear();ui.limit=30;updateRoute();render('#search');document.getElementById('search').setSelectionRange(caret,caret);return;}if(n.dataset.edit){const k=n.dataset.edit,t=editCopy(working.id);t.proposed[k]=n.value;choose(t,k,'custom');syncInclude(t);working=t;markDirty();return;}if(n.dataset.note){const k=n.dataset.note,t=editCopy(working.id);if(!t.decisions[k]){t.decisions[k]={choice:undefined,note:'',at:stamp(),epic:t.epic[k],olsd:t.olsd[k]};}t.decisions[k].note=n.value;working=t;markDirty();}});
document.addEventListener('change',ev=>{const n=ev.target;if(n.id==='role'){const next=n.value;guard(()=>{state.role=next;ui.selected.clear();ui.undo=null;persist();render();},()=>document.getElementById('role').value=state.role);return;}if(n.id==='lab-filter'){ui.lab=n.value;ui.selected.clear();ui.approvalSelection.clear();ui.downloadSelection.clear();ui.limit=30;render('#lab-filter');return;}if(n.id==='all-filter'){ui.allFilter=n.value;ui.limit=30;render('#all-filter');return;}if(n.dataset.downloadSelect){n.checked?ui.downloadSelection.add(n.dataset.downloadSelect):ui.downloadSelection.delete(n.dataset.downloadSelect);render(`[data-download-select="${n.dataset.downloadSelect}"]`);return;}if(n.dataset.approveSelect){n.checked?ui.approvalSelection.add(n.dataset.approveSelect):ui.approvalSelection.delete(n.dataset.approveSelect);render(`[data-approve-select="${n.dataset.approveSelect}"]`);return;}if(n.dataset.selectTest){ui.saveResult=null;for(const k of selectionKeys(byId(n.dataset.selectTest)))n.checked?ui.selected.add(n.dataset.selectTest+'|'+k):ui.selected.delete(n.dataset.selectTest+'|'+k);render(`[data-select-test="${n.dataset.selectTest}"]`);return;}if(n.dataset.select){ui.saveResult=null;n.checked?ui.selected.add(n.dataset.select):ui.selected.delete(n.dataset.select);render(`[data-select="${n.dataset.select}"]`);return;}if(n.dataset.category){const checked=n.checked;if(!checked&&working.olsd.categories.split(';').includes(n.dataset.category))n.checked=true;editCategory(n.dataset.category,checked);}});
document.addEventListener('toggle',ev=>{const k=ev.target.dataset?.detail;if(k)ev.target.open?ui.details.add(k):ui.details.delete(k);},true);
document.addEventListener('keydown',ev=>{const root=document.getElementById('modal-root');if(root.innerHTML){if(ev.key==='Escape'){ev.preventDefault();closeModal(true);}if(ev.key==='Tab'){const nodes=[...root.querySelectorAll('button,input,textarea,select,a[href]')],first=nodes[0],last=nodes.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}return;}
 if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='s'){ev.preventDefault();if(dirtyNow())saveWithNavigation('stay');return;}
 if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;
 if(view==='test'&&['1','2'].includes(ev.key)){const k=questionKey(working);if(k){const choice=ev.key==='1'?'epic':'olsd';if(choice!=='epic'||working.epic[k]!=null){ev.preventDefault();chooseAnswer(k,choice);}}}
});
window.addEventListener('beforeunload',ev=>{if(dirtyNow()){ev.preventDefault();ev.returnValue='';}});
function browserRoute(){if(location.hash===currentHash)return;const next=location.hash;guard(()=>loadRoute(next),()=>history.pushState({},'',currentHash));}
window.addEventListener('popstate',browserRoute);window.addEventListener('hashchange',browserRoute);
persist();if(!location.hash)history.replaceState({},'','#/worklist?tab=review');loadRoute(location.hash);
